package com.fooddelivery.delivery.entity;
import jakarta.persistence.*;import java.math.BigDecimal;import java.time.LocalDateTime;
@Entity @Table(name="driver_presence")public class DriverPresence{@Id @Column(name="user_id")private Long userId;@Column(nullable=false,precision=10,scale=7)private BigDecimal latitude;@Column(nullable=false,precision=10,scale=7)private BigDecimal longitude;@Column(nullable=false)private boolean available;@Column(name="updated_at",insertable=false,updatable=false)private LocalDateTime updatedAt;protected DriverPresence(){}public DriverPresence(Long userId,BigDecimal lat,BigDecimal lon,boolean available){this.userId=userId;latitude=lat;longitude=lon;this.available=available;}public Long getUserId(){return userId;}public BigDecimal getLatitude(){return latitude;}public BigDecimal getLongitude(){return longitude;}public boolean isAvailable(){return available;}public void update(BigDecimal lat,BigDecimal lon,boolean available){latitude=lat;longitude=lon;this.available=available;}}
